1	// Thin Anthropic Messages API wrapper for the "Build with Claude AI" feature.
2	// No SDK / no new deps — plain fetch. BYOK: each request is made with the
3	// OWNER'S effective key (their stored key, else the optional platform key).
4	
5	import { decryptSecret } from "./crypto-box";
6	
7	const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
8	const MODEL = "claude-opus-4-8";
9	
10	export type ClaudeMessage = { role: "user" | "assistant"; content: string };
11	
12	/** True when an optional platform-wide fallback key is configured. */
13	export function platformKeyConfigured(): boolean {
14	  return Boolean(process.env.ANTHROPIC_API_KEY && process.env.ANTHROPIC_API_KEY.trim());
15	}
16	
17	/** Deprecated alias kept for backwards compatibility. */
18	export function anthropicConfigured(): boolean {
19	  return platformKeyConfigured();
20	}
21	
22	/**
23	 * Resolve the effective key for a user: their own decrypted BYOK key if present,
24	 * otherwise the optional platform-wide ANTHROPIC_API_KEY. Returns null if neither
25	 * is available. Never throws on a bad/absent stored key (decryptSecret returns null).
26	 */
27	export function effectiveKeyFor(
28	  user: { anthropicKeyEnc?: string | null } | null | undefined
29	): string | null {
30	  const own = decryptSecret(user?.anthropicKeyEnc ?? null);
31	  if (own && own.trim()) return own.trim();
32	  const platform = process.env.ANTHROPIC_API_KEY;
33	  return platform && platform.trim() ? platform.trim() : null;
34	}
35	
36	/**
37	 * Send a chat turn to Claude and return the concatenated text of the reply.
38	 * The caller supplies the API key (the build owner's effective key).
39	 * Throws when the key is missing or the API returns a non-2xx response.
40	 */
41	export async function askClaude(
42	  apiKey: string,
43	  messages: ClaudeMessage[],
44	  system: string,
45	  opts: { maxTokens?: number; timeoutMs?: number } = {}
46	): Promise<string> {
47	  if (!apiKey) throw new Error("No Anthropic API key available");
48	
49	  const controller = new AbortController();
50	  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 60_000);
51	  let res: Response;
52	  try {
53	    res = await fetch(ANTHROPIC_URL, {
54	      method: "POST",
55	      headers: {
56	        "content-type": "application/json",
57	        "x-api-key": apiKey,
58	        "anthropic-version": "2023-06-01",
59	      },
60	      body: JSON.stringify({
61	        model: MODEL,
62	        max_tokens: opts.maxTokens ?? 1024,
63	        system,
64	        messages,
65	      }),
66	      signal: controller.signal,
67	    });
68	  } finally {
69	    clearTimeout(timer);
70	  }
71	
72	  if (!res.ok) {
73	    const body = await res.text().catch(() => "");
74	    throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 500)}`);
75	  }
76	
77	  const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
78	  const text = (data.content ?? [])
79	    .filter((b) => b.type === "text" && typeof b.text === "string")
80	    .map((b) => b.text as string)
81	    .join("")
82	    .trim();
83	  return text;
84	}
