1	/**
2	 * Marketing Agent Phase 1 — DRAFT GENERATION.
3	 *
4	 * Turns a detected MarketingSignal into a DISCLOSED draft reply using the same
5	 * server-side Anthropic access the "Build with Claude AI" feature uses
6	 * (lib/anthropic.ts, platform ANTHROPIC_API_KEY). The draft is a STARTING POINT
7	 * for a human to rewrite in their own voice and post MANUALLY — this module
8	 * never posts anything.
9	 *
10	 * Honesty guardrails baked into the prompt AND enforced after generation:
11	 *  - Always transparently discloses the Nxeon affiliation (the DISCLOSURE line).
12	 *  - Genuinely answers the poster's actual question first.
13	 *  - No fabricated reviews, fake benchmarks, invented customers or specifics.
14	 *  - If no API key is configured, we skip gracefully and return null so the
15	 *    caller can leave the signal at NEW with a note (no silent failure).
16	 */
17	
18	import { askClaude, platformKeyConfigured } from "../anthropic";
19	import { DISCLOSURE, buildDisclosedDraft, isDisclosed } from "./community-monitor";
20	
21	const DRAFT_SYSTEM_PROMPT = `You draft honest, helpful, DISCLOSED replies to public discussions (Reddit, Hacker News, forums) where someone is asking for hosting / VPS / game-server recommendations. Nxeon is an NVMe VPS + game-server host: full root, DDoS protection, free migration, and the price you sign up at is the price you renew at (no renewal price hikes).
22	
23	A HUMAN will review, edit and post your draft manually from a real account. You are NOT posting anything.
24	
25	Write the draft with these rules, in order of importance:
26	1. Genuinely help the poster FIRST. Answer their actual question. If Nxeon does not fit their need, say so — a useful, honest reply is the whole point.
27	2. Be transparent: the reply MUST end with this exact disclosure line on its own line: "${DISCLOSURE}"
28	3. Never fabricate: no invented benchmarks, no fake reviews, no made-up customers, no specific uptime/price numbers you were not given. Only mention the general facts above.
29	4. No spam, no hard sell, no links unless obviously helpful. Conversational, short (3–6 sentences), matches a real person's tone.
30	5. Do NOT claim to be a neutral customer. You are disclosed as working on Nxeon.
31	
32	Output ONLY the reply text (no preamble, no markdown headers, no quotes).`;
33	
34	/**
35	 * Generate a disclosed draft for a signal. Returns the draft body on success,
36	 * or null when no Anthropic key is configured (caller records a note + leaves
37	 * the signal NEW). On an API error it also returns null.
38	 */
39	export async function generateDraft(signal: {
40	  title: string;
41	  excerpt: string;
42	  url: string;
43	  matchedKeywords: string[];
44	}): Promise<string | null> {
45	  if (!platformKeyConfigured()) return null;
46	  const key = process.env.ANTHROPIC_API_KEY!.trim();
47	
48	  const userMsg =
49	    `A public post to reply to:\n\n` +
50	    `Title: ${signal.title || "(no title)"}\n` +
51	    `Body/excerpt: ${signal.excerpt || "(no body)"}\n` +
52	    `Matched signals: ${signal.matchedKeywords.join(", ") || "(none)"}\n\n` +
53	    `Write a helpful, honest, disclosed draft reply.`;
54	
55	  let text: string;
56	  try {
57	    text = await askClaude(key, [{ role: "user", content: userMsg }], DRAFT_SYSTEM_PROMPT, {
58	      maxTokens: 600,
59	      timeoutMs: 45_000,
60	    });
61	  } catch {
62	    return null;
63	  }
64	
65	  if (!text || !text.trim()) return null;
66	
67	  // Enforce disclosure even if the model omitted it — never post undisclosed.
68	  let body = text.trim();
69	  if (!isDisclosed(body)) {
70	    body = `${body}\n\n${DISCLOSURE}`;
71	  }
72	  return body;
73	}
74	
75	/**
76	 * Deterministic fallback draft (no API needed) — reuses the pure disclosed-draft
77	 * builder. Used when a human forces a draft but no key is set, so the queue is
78	 * still reviewable.
79	 */
80	export function fallbackDraft(excerpt: string): string {
81	  return buildDisclosedDraft({ context: excerpt });
82	}
