import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { BusinessCreateForm, BusinessImportForm, BusinessRowActions } from "@/components/admin/coldemail/Controls";

export const dynamic = "force-dynamic";

const SOURCE_LABEL: Record<string, string> = { manual: "Manual", csv: "CSV" };

export default async function ColdEmailBusinesses() {
  await requireArea("platform");

  const businesses = await db.business.findMany({
    orderBy: { createdAt: "desc" },
    include: {
      contacts: {
        orderBy: { createdAt: "asc" },
        include: { consentRecords: { select: { id: true }, take: 1 } },
      },
    },
    take: 500,
  });

  return (
    <div className="space-y-6">
      <PageHeader title="Businesses" sub="Manual and CSV data only — no scraping or enrichment happens in Phase 1." />

      <div className="card">
        <p className="section-label mb-4">Add a business</p>
        <BusinessCreateForm />
      </div>

      <div className="card">
        <p className="section-label mb-4">Import from CSV</p>
        <BusinessImportForm />
      </div>

      <div className="card overflow-x-auto p-0">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">All businesses</p>
          <p className="text-xs text-slate-500">{businesses.length} shown</p>
        </div>
        {businesses.length === 0 ? (
          <div className="p-4">
            <EmptyState title="No businesses yet" sub="Add one above or paste a CSV to get started." />
          </div>
        ) : (
          <table className="table-shell mt-2 min-w-[960px]">
            <thead>
              <tr>
                <th>Business</th>
                <th>Category</th>
                <th>Location</th>
                <th>Primary contact</th>
                <th>Consent</th>
                <th>Source</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {businesses.map((b) => {
                const contact = b.contacts[0];
                const hasConsent = (contact?.consentRecords.length ?? 0) > 0;
                return (
                  <tr key={b.id}>
                    <td className="align-top">
                      <div className="font-medium text-white">{b.name}</div>
                      {b.website && <div className="text-xs text-slate-500">{b.website}</div>}
                    </td>
                    <td className="align-top text-slate-400">{b.category || "—"}</td>
                    <td className="align-top text-slate-400">
                      {[b.city, b.region, b.country].filter(Boolean).join(", ") || "—"}
                    </td>
                    <td className="align-top">
                      {contact ? (
                        <>
                          <div className="text-sm text-slate-200">{contact.fullName || contact.email}</div>
                          <div className="text-xs text-slate-500">{contact.email}</div>
                        </>
                      ) : (
                        <span className="text-slate-600">—</span>
                      )}
                    </td>
                    <td className="align-top">
                      {contact ? (
                        hasConsent ? (
                          <Badge tone="green">recorded</Badge>
                        ) : (
                          <Badge tone="amber">none</Badge>
                        )
                      ) : (
                        <span className="text-slate-600">—</span>
                      )}
                    </td>
                    <td className="align-top text-slate-400">{SOURCE_LABEL[b.source] ?? b.source}</td>
                    <td className="align-top">
                      <BusinessRowActions id={b.id} contactId={contact?.id} hasConsent={hasConsent} />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
