/**
 * Sitewave — brand + module configuration.
 *
 * PLACEHOLDER BRAND. "Sitewave" is a working name for the productized web-design
 * agency add-on. The domain is stored here as config, NOT resolved via DNS — no
 * subdomain is provisioned in Phase 1 (deploy-to-subdomain is a stub).
 */

export const SITEWAVE = {
  /** Display name used across the admin UI + on generated demos. */
  name: "Sitewave",
  tagline: "Websites that win you customers.",
  /** Placeholder demo domain. Config only — do NOT rely on DNS resolving this. */
  demoDomain: "agency.revsports.ca",
  palette: {
    indigo: "#4F46E5",
    coral: "#FB7185",
    ink: "#0B1020",
  },
} as const;

/**
 * The intended host for a demo's would-be subdomain. Recorded on the "Deploy to
 * subdomain" stub; never actually provisioned in Phase 1.
 */
export function intendedHostFor(slug: string): string {
  return `${slug}.${SITEWAVE.demoDomain}`;
}

/** The mandatory affiliation disclaimer, per the legal guardrails (arch §11). */
export function disclaimerFor(businessName: string): string {
  const name = businessName.trim() || "this business";
  return `Independent concept — not affiliated with ${name}. Unofficial redesign by ${SITEWAVE.name}.`;
}

/**
 * Sitewave — Site IR (Intermediate Representation) + section-schema types and
 * validation.
 *
 * The generator (lib/agency/generate.ts) emits a Site IR, NOT raw HTML. The
 * deterministic renderer (lib/agency/render.ts) maps a validated IR to a
 * self-contained static HTML page. Validation lives here so both the LLM path
 * and the fallback path produce the exact same, safe shape.
 *
 * This module is pure (no imports of db / next / anthropic) so it can be unit
 * tested and reused server-side without side effects.
 */

// ---------------------------------------------------------------------------
// Section schema — what a vertical template constrains the generated site to.
// ---------------------------------------------------------------------------

export type SectionKey = "hero" | "services" | "about" | "testimonials" | "contact";

export const SECTION_KEYS: SectionKey[] = ["hero", "services", "about", "testimonials", "contact"];

export type SectionSchemaEntry = {
  key: SectionKey;
  label: string;
  required: boolean;
  /** Human guidance fed to the LLM for this section's copy. */
  guidance: string;
};

export type TemplateStructure = {
  sections: SectionSchemaEntry[];
  /** Optional palette hint the template suggests to the generator. */
  palette?: { primary?: string; accent?: string };
};

/** Narrow an unknown Json value from Prisma into a TemplateStructure, defensively. */
export function asTemplateStructure(value: unknown): TemplateStructure {
  const v = (value ?? {}) as { sections?: unknown; palette?: unknown };
  const rawSections = Array.isArray(v.sections) ? v.sections : [];
  const sections: SectionSchemaEntry[] = rawSections
    .map((s) => s as Partial<SectionSchemaEntry>)
    .filter((s): s is SectionSchemaEntry => typeof s?.key === "string" && SECTION_KEYS.includes(s.key as SectionKey))
    .map((s) => ({
      key: s.key,
      label: String(s.label ?? s.key),
      required: Boolean(s.required),
      guidance: String(s.guidance ?? ""),
    }));
  const palette = (v.palette ?? undefined) as TemplateStructure["palette"];
  return { sections, palette };
}

// ---------------------------------------------------------------------------
// Site IR — the structured output the generator produces.
// ---------------------------------------------------------------------------

export type IRService = { name: string; description: string };
export type IRTestimonial = { quote: string; author: string };

export type SiteIR = {
  businessName: string;
  vertical: string;
  hero: { headline: string; subheadline: string; ctaLabel: string };
  services: IRService[];
  about: string;
  testimonials: IRTestimonial[];
  contact: { ctaHeadline: string; ctaBody: string; buttonLabel: string };
  /** A suggested — INSPIRED-BY, not exact-brand — palette (legal guardrail). */
  palette: { primary: string; accent: string };
};

const HEX = /^#[0-9a-fA-F]{6}$/;

function str(v: unknown, fallback = ""): string {
  return typeof v === "string" && v.trim() ? v.trim() : fallback;
}

function clampArray<T>(v: unknown, map: (x: unknown) => T | null, max: number): T[] {
  if (!Array.isArray(v)) return [];
  const out: T[] = [];
  for (const item of v) {
    const m = map(item);
    if (m) out.push(m);
    if (out.length >= max) break;
  }
  return out;
}

/**
 * Coerce an arbitrary object (LLM JSON or a fallback build) into a fully-valid
 * SiteIR. NEVER throws: every field is defaulted so the renderer always has a
 * safe, complete IR. `defaults` supplies sensible per-vertical text when a field
 * is missing (used by the deterministic fallback).
 */
export function coerceSiteIR(
  raw: unknown,
  defaults: { businessName: string; vertical: string; palette?: { primary: string; accent: string } }
): SiteIR {
  const o = (raw ?? {}) as Record<string, unknown>;
  const hero = (o.hero ?? {}) as Record<string, unknown>;
  const contact = (o.contact ?? {}) as Record<string, unknown>;
  const paletteIn = (o.palette ?? {}) as Record<string, unknown>;

  const primary = HEX.test(str(paletteIn.primary)) ? str(paletteIn.primary) : (defaults.palette?.primary ?? "#4F46E5");
  const accent = HEX.test(str(paletteIn.accent)) ? str(paletteIn.accent) : (defaults.palette?.accent ?? "#FB7185");

  return {
    businessName: str(o.businessName, defaults.businessName),
    vertical: str(o.vertical, defaults.vertical),
    hero: {
      headline: str(hero.headline, `${defaults.businessName}`),
      subheadline: str(hero.subheadline, "A better website, built to win you customers."),
      ctaLabel: str(hero.ctaLabel, "Get in touch"),
    },
    services: clampArray<IRService>(
      o.services,
      (x) => {
        const s = (x ?? {}) as Record<string, unknown>;
        const name = str(s.name);
        if (!name) return null;
        return { name, description: str(s.description, "") };
      },
      8
    ),
    about: str(o.about, ""),
    testimonials: clampArray<IRTestimonial>(
      o.testimonials,
      (x) => {
        const t = (x ?? {}) as Record<string, unknown>;
        const quote = str(t.quote);
        if (!quote) return null;
        return { quote, author: str(t.author, "Happy customer") };
      },
      6
    ),
    contact: {
      ctaHeadline: str(contact.ctaHeadline, "Ready to get started?"),
      ctaBody: str(contact.ctaBody, "Reach out and we'll get back to you shortly."),
      buttonLabel: str(contact.buttonLabel, "Contact us"),
    },
    palette: { primary, accent },
  };
}

/** True when an IR has the minimum content to render a credible page. */
export function isRenderableIR(ir: SiteIR): boolean {
  return Boolean(ir.hero.headline) && ir.services.length > 0 && Boolean(ir.contact.ctaHeadline);
}

/** Slugify a business name into a subdomain-safe label. */
export function slugify(input: string): string {
  const s = input
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  return s || "demo";
}

/**
 * Sitewave — starter per-vertical template library.
 *
 * The single source of truth for the seed verticals + their section schemas.
 * `prisma/seed-agency.ts` writes these to the DB; the generator's deterministic
 * fallback (lib/agency/generate.ts) reads the same data so a demo can be built
 * with NO database and NO API key. Pure data + helpers — no side effects.
 */

