  { key: "testimonials", label: "Testimonials", required: false, guidance: "2–3 short, believable customer quotes (no invented names of real people)." },
  { key: "contact", label: "Contact", required: true, guidance: "A closing CTA inviting the visitor to get in touch or book." },
