/** Look up a vertical seed by slug (case-insensitive). */
export function verticalBySlug(slug: string): VerticalSeed | undefined {
  const s = slug.trim().toLowerCase();
  return VERTICALS.find((v) => v.slug === s);
}

/**
 * Build a complete, deterministic SiteIR from a vertical's fallback content.
 * Used when no API key is set or an LLM call fails — the module always produces
 * a credible demo.
 */
export function fallbackIR(businessName: string, slug: string): SiteIR {
  const v = verticalBySlug(slug) ?? VERTICALS[0];
  const f = v.fallback;
  const name = businessName.trim() || v.name;
  return {
    businessName: name,
    vertical: v.slug,
    hero: {
      headline: f.hero.headline,
      subheadline: f.hero.subheadline,
      ctaLabel: f.hero.ctaLabel,
    },
    services: f.services.map((s) => ({ ...s })),
    about: f.about,
    testimonials: f.testimonials.map((t) => ({ ...t })),
    contact: { ...f.contact },
    palette: { ...f.palette },
  };
}

/**
 * Sitewave — spec-site GENERATOR core.
 *
 * Given a prospect (business name, vertical, optional PASTED existing-site text
 * — never scraped), produce a structured Site IR constrained to the vertical's
 * section schema. Uses the platform Anthropic key via lib/anthropic.ts (askClaude).
 *
 * Degrades gracefully, exactly like lib/marketing/draft-gen.ts: if no
 * ANTHROPIC_API_KEY is configured (or the call fails / returns unusable JSON),
 * it falls back to the deterministic per-vertical template fill so a demo is
 * ALWAYS produced. Every path returns a fully-valid, coerced SiteIR.
 *
 * This module performs NO scraping and NO network fetch of the prospect's site —
 * `pastedSiteText` is operator-supplied context only.
 */

import { askClaude, platformKeyConfigured } from "../anthropic";
import { coerceSiteIR, type SiteIR, type TemplateStructure } from "./schema";
import { fallbackIR, verticalBySlug } from "./templates";
import { SITEWAVE } from "./config";

const GEN_MODEL = "claude-opus-4-8";

export type GenerateInput = {
  businessName: string;
  vertical: string;
  slug: string;
  pastedSiteText?: string;
  structure?: TemplateStructure;
};

export type GenerateResult = {
  ir: SiteIR;
  /** "llm" when askClaude produced usable JSON, else "fallback". */
  mode: "llm" | "fallback";
  model: string;
  ok: boolean;
  message: string;
};

function buildSystemPrompt(structure: TemplateStructure | undefined, vertical: string): string {
  const v = verticalBySlug(vertical);
  const sectionList = (structure?.sections ?? [])
    .map((s) => `- ${s.key}${s.required ? " (required)" : ""}: ${s.guidance}`)
    .join("\n");

  return `You are a senior web copywriter for ${SITEWAVE.name}, a web-design studio. You write a concept redesign for a local ${v?.name ?? vertical} business.

You output ONLY a single JSON object (no prose, no markdown fences) matching this exact shape:
{
  "businessName": string,
  "vertical": string,
  "hero": { "headline": string, "subheadline": string, "ctaLabel": string },
  "services": [ { "name": string, "description": string } ],   // 3 to 6 items
  "about": string,
  "testimonials": [ { "quote": string, "author": string } ],   // 2 to 3 items
  "contact": { "ctaHeadline": string, "ctaBody": string, "buttonLabel": string },
  "palette": { "primary": "#RRGGBB", "accent": "#RRGGBB" }
}

Section guidance:
${sectionList || "- hero, services, about, testimonials, contact"}

${v?.promptHint ? `Vertical tone: ${v.promptHint}` : ""}

HARD RULES (legal + quality):
1. Use the business name as PLAIN TEXT only. Never describe or reference a logo.
2. palette must be an INSPIRED-BY scheme appropriate to the vertical — do NOT try to reproduce the business's exact brand colors. Return valid 6-digit hex.
3. testimonials must be GENERIC and clearly illustrative — never invent named real people or fabricate specific verifiable claims (no fake star counts, awards, or statistics).
4. Rewrite everything in fresh words. Never copy sentences verbatim from any provided existing-site text.
5. Keep copy concise and benefit-led. Output must be valid JSON and nothing else.`;
}

/** Pull the first balanced top-level JSON object out of a model reply. */
function extractJson(text: string): unknown | null {
  const trimmed = text.trim();
  // Fast path: the whole reply is JSON.
  try {
    return JSON.parse(trimmed);
  } catch {
    // fall through to brace scan
  }
  const start = trimmed.indexOf("{");
  if (start < 0) return null;
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < trimmed.length; i++) {
    const c = trimmed[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        const slice = trimmed.slice(start, i + 1);
        try {
          return JSON.parse(slice);
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

/**
 * Generate a Site IR for a prospect. Never throws; always returns a renderable
 * IR. When `mode === "fallback"` the deterministic per-vertical fill was used.
 */
export async function generateSiteIR(input: GenerateInput): Promise<GenerateResult> {
  const vertical = input.vertical.trim() || "dentist";
  const seed = verticalBySlug(vertical) ?? verticalBySlug("dentist")!;
  const defaults = {
    businessName: input.businessName.trim() || seed.name,
    vertical: seed.slug,
    palette: seed.fallback.palette,
  };
  const fallback: GenerateResult = {
    ir: fallbackIR(input.businessName, seed.slug),
    mode: "fallback",
    model: "",
    ok: true,
    message: "Deterministic template fill (no LLM).",
  };

  if (!platformKeyConfigured()) {
    return { ...fallback, message: "No ANTHROPIC_API_KEY configured — used deterministic template fill." };
  }

  const key = process.env.ANTHROPIC_API_KEY!.trim();
  const structure = input.structure ?? seed.structure;
  const system = buildSystemPrompt(structure, seed.slug);

  const pasted = (input.pastedSiteText ?? "").trim().slice(0, 4000);
  const userMsg =
    `Business name: ${input.businessName.trim() || "(unnamed)"}\n` +
    `Vertical: ${seed.name}\n` +
    (pasted
      ? `\nContext pasted from their existing site (rewrite, do NOT copy):\n"""\n${pasted}\n"""\n`
      : `\n(No existing-site text provided — write from the vertical alone.)\n`) +
    `\nReturn the JSON object now.`;

  let text: string;
  try {
    text = await askClaude(key, [{ role: "user", content: userMsg }], system, {
      maxTokens: 1800,
      timeoutMs: 60_000,
    });
  } catch (err) {
    return { ...fallback, ok: false, message: `LLM call failed, used fallback: ${String(err).slice(0, 200)}` };
  }

  const parsed = extractJson(text);
  if (!parsed) {
    return { ...fallback, ok: false, message: "LLM returned unparseable JSON — used fallback." };
  }

  const ir = coerceSiteIR(parsed, defaults);
  // If the model produced no services, prefer the fallback's fuller content.
  if (ir.services.length === 0) {
    return { ...fallback, ok: false, message: "LLM output had no services — used fallback." };
  }

  return { ir, mode: "llm", model: GEN_MODEL, ok: true, message: "Generated via Claude." };
}

/**
 * Sitewave — DETERMINISTIC renderer: Site IR -> self-contained static HTML.
 *
 * Pure + deterministic (same IR in => byte-identical HTML out, no clock, no
 * randomness, no network). Produces a single self-contained page: inline CSS,
 * no external requests, no re-hosted assets.
 *
 * LEGAL GUARDRAILS baked in (architecture §11 — the biggest risk):
 *  - The business NAME appears in plain type only. No logo is referenced or
 *    re-hosted.
 *  - An INSPIRED-BY / neutral palette (from the IR's palette suggestion) — the
 *    renderer never claims to reproduce the business's exact brand.
 *  - A visible "Independent concept — not affiliated with {business}" disclaimer
 *    in the header banner AND the footer.
 *  - <meta name="robots" content="noindex, nofollow"> so the demo can never rank
 *    or be mistaken for the real site.
 *
 * All IR-derived text is HTML-escaped — the renderer never injects raw markup.
 */

import type { SiteIR } from "./schema";
import { SITEWAVE, disclaimerFor } from "./config";

/** Escape the five HTML-significant characters. */
export function esc(s: string): string {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Sanitize a hex color to a safe `#rrggbb`, else a neutral default. */
function safeHex(v: string, fallback: string): string {
  return /^#[0-9a-fA-F]{6}$/.test(v) ? v : fallback;
}

export type RenderResult = {
  html: string;
  /** True when every mandatory legal guardrail is present in the output. */
  guardrailsOk: boolean;
};

/**
 * Render a validated Site IR to a complete HTML document string. Never throws.
 */
export function renderSiteHtml(ir: SiteIR): RenderResult {
  const name = esc(ir.businessName || "This business");
  const primary = safeHex(ir.palette.primary, SITEWAVE.palette.indigo);
  const accent = safeHex(ir.palette.accent, SITEWAVE.palette.coral);
  const disclaimer = esc(disclaimerFor(ir.businessName));
  const year = 2026; // fixed so output is deterministic (no Date.now()).

  const services = ir.services
    .map(
      (s) => `        <div class="card">
          <h3>${esc(s.name)}</h3>
          <p>${esc(s.description)}</p>
        </div>`
    )
    .join("\n");

  const testimonials = ir.testimonials
    .map(
      (t) => `        <figure class="quote">
          <blockquote>&ldquo;${esc(t.quote)}&rdquo;</blockquote>
          <figcaption>${esc(t.author)}</figcaption>
        </figure>`
    )
    .join("\n");

  const aboutBlock = ir.about
    ? `    <section id="about" class="section">
      <div class="wrap narrow">
        <h2>About ${name}</h2>
        <p class="lead">${esc(ir.about)}</p>
      </div>
    </section>`
    : "";

  const testimonialsBlock = ir.testimonials.length
    ? `    <section id="testimonials" class="section alt">
      <div class="wrap">
        <h2>What people say</h2>
        <div class="quotes">
${testimonials}
        </div>
        <p class="fineprint">Illustrative testimonials for this concept — not real customer statements.</p>
      </div>
    </section>`
    : "";

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="robots" content="noindex, nofollow">
  <title>${name} — concept redesign by ${esc(SITEWAVE.name)}</title>
  <style>
    :root { --primary: ${primary}; --accent: ${accent}; --ink: ${SITEWAVE.palette.ink}; }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #1f2430; line-height: 1.6; background: #fff; }
    a { color: var(--primary); }
    .wrap { max-width: 1080px; margin: 0 auto; padding: 0 24px; }
    .narrow { max-width: 760px; }
    .disclaimer-bar { background: var(--ink); color: #cdd3e0; font-size: 13px; text-align: center; padding: 8px 16px; }
    header.hero { background: linear-gradient(135deg, var(--primary), var(--accent)); color: #fff; padding: 96px 0 88px; text-align: center; }
    header.hero h1 { font-size: clamp(32px, 6vw, 56px); margin: 0 0 16px; line-height: 1.1; }
    header.hero p { font-size: clamp(17px, 2.4vw, 22px); max-width: 640px; margin: 0 auto 28px; opacity: .95; }
    .btn { display: inline-block; background: #fff; color: var(--primary); font-weight: 700; text-decoration: none; padding: 14px 28px; border-radius: 999px; }
    .btn.solid { background: var(--primary); color: #fff; }
    .brandline { text-transform: uppercase; letter-spacing: .18em; font-size: 13px; opacity: .85; margin: 0 0 20px; }
    .section { padding: 72px 0; }
    .section.alt { background: #f6f7fb; }
    .section h2 { font-size: clamp(26px, 4vw, 38px); margin: 0 0 32px; text-align: center; }
    .lead { font-size: 19px; text-align: center; color: #3a4152; }
    .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
    .card { background: #fff; border: 1px solid #e7e9f2; border-radius: 16px; padding: 24px; }
    .card h3 { margin: 0 0 8px; color: var(--primary); font-size: 19px; }
    .card p { margin: 0; color: #4a5162; }
    .quotes { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 20px; }
    .quote { margin: 0; background: #fff; border: 1px solid #e7e9f2; border-radius: 16px; padding: 24px; }
    .quote blockquote { margin: 0 0 12px; font-size: 18px; color: #2a3040; }
    .quote figcaption { color: #7a8194; font-weight: 600; }
