    footer.site strong { color: #cdd3e0; }
  </style>
</head>
<body>
  <div class="disclaimer-bar">${disclaimer}</div>

  <header class="hero">
    <div class="wrap">
      <p class="brandline">${name}</p>
      <h1>${esc(ir.hero.headline)}</h1>
      <p>${esc(ir.hero.subheadline)}</p>
      <a class="btn" href="#contact">${esc(ir.hero.ctaLabel)}</a>
    </div>
  </header>

  <main>
    <section id="services" class="section">
      <div class="wrap">
        <h2>Our services</h2>
        <div class="grid">
${services}
        </div>
