    </section>

${aboutBlock}

${testimonialsBlock}

    <section id="contact" class="cta">
      <div class="wrap narrow">
        <h2>${esc(ir.contact.ctaHeadline)}</h2>
        <p>${esc(ir.contact.ctaBody)}</p>
