  // Assert every mandatory guardrail actually made it into the output.
  const guardrailsOk =
    html.includes('name="robots"') &&
    html.includes("noindex") &&
    html.includes("Independent concept — not affiliated with") &&
    html.includes(esc(SITEWAVE.name));

  return { html, guardrailsOk };
}

"use server";

/**
 * Sitewave (Marketing Agency) — admin server actions. PHASE 1.
 *
 * Every action re-checks requireArea("platform"). Guardrails, per the build
 * plan: NOTHING here scrapes a live site, sends outreach, or provisions a real
 * subdomain. "Generate demo" runs the pure generator + deterministic renderer;
 * "Deploy to subdomain" only marks a demo DEPLOYED_STUB and records the intended
 * host; "Send to outreach" creates/links a Cold Email Business+Contact but sends
 * nothing.
 */

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { logEvent } from "@/lib/log";
import { generateSiteIR } from "@/lib/agency/generate";
import { renderSiteHtml } from "@/lib/agency/render";
import { asTemplateStructure, slugify, type SiteIR } from "@/lib/agency/schema";
import { intendedHostFor } from "@/lib/agency/config";
import type { Prisma } from "@prisma/client";

type ActionState = { error?: string; ok?: boolean };

// ---------------------------------------------------------------------------
// Verticals + templates
// ---------------------------------------------------------------------------

const verticalSchema = z.object({
  slug: z.string().trim().min(1, "A slug is required.").max(60),
  name: z.string().trim().min(1, "A name is required.").max(120),
  description: z.string().trim().max(400).default(""),
});

export async function createVertical(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = verticalSchema.safeParse({
    slug: formData.get("slug"),
    name: formData.get("name"),
    description: formData.get("description") ?? "",
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid vertical." };
  const slug = slugify(parsed.data.slug);

  const clash = await db.agencyVertical.findUnique({ where: { slug }, select: { id: true } });
  if (clash) return { error: "A vertical with that slug already exists." };

  try {
    await db.agencyVertical.create({
      data: { slug, name: parsed.data.name, description: parsed.data.description },
    });
  } catch (err) {
    await logEvent("error", "agency.vertical.create", { message: String(err) });
    return { error: "Could not create the vertical." };
  }
  revalidatePath("/admin/agency/verticals");
  revalidatePath("/admin/agency");
  return { ok: true };
}

export async function deleteVertical(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.agencyVertical.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/agency/verticals");
  revalidatePath("/admin/agency");
  return { ok: true };
}

const templateSchema = z.object({
  verticalId: z.string().trim().min(1, "Choose a vertical."),
  name: z.string().trim().min(1, "A template name is required.").max(120),
});

/**
 * Create a template. The section schema is seeded to the five standard sections
 * (hero, services, about, testimonials, contact) so a template is immediately
 * usable; richer authoring is Phase 2.
 */
export async function createTemplate(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = templateSchema.safeParse({
    verticalId: formData.get("verticalId"),
    name: formData.get("name"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid template." };

  const vertical = await db.agencyVertical.findUnique({ where: { id: parsed.data.verticalId }, select: { id: true } });
  if (!vertical) return { error: "That vertical no longer exists." };

  const structure = {
    sections: [
      { key: "hero", label: "Hero", required: true, guidance: "Headline + supporting line + call to action." },
      { key: "services", label: "Services", required: true, guidance: "3–6 core services." },
      { key: "about", label: "About", required: false, guidance: "A short trust-building paragraph." },
      { key: "testimonials", label: "Testimonials", required: false, guidance: "2–3 generic illustrative quotes." },
      { key: "contact", label: "Contact", required: true, guidance: "Closing CTA." },
    ],
  } satisfies Prisma.InputJsonValue;

  try {
    await db.agencyTemplate.create({
      data: { verticalId: parsed.data.verticalId, name: parsed.data.name, structure },
    });
  } catch (err) {
    await logEvent("error", "agency.template.create", { message: String(err) });
    return { error: "Could not create the template." };
  }
  revalidatePath("/admin/agency/verticals");
  revalidatePath("/admin/agency");
  return { ok: true };
}

export async function deleteTemplate(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.agencyTemplate.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/agency/verticals");
  revalidatePath("/admin/agency");
