const prospectSchema = z.object({
  businessName: z.string().trim().min(1, "A business name is required.").max(160),
  vertical: z.string().trim().max(60).default(""),
  contactEmail: z.string().trim().max(200).default(""),
  currentSiteUrl: z.string().trim().max(300).default(""),
  pastedSiteText: z.string().trim().max(20000).default(""),
  notes: z.string().trim().max(2000).default(""),
});

const emailCheck = z.string().email();

export async function addProspect(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = prospectSchema.safeParse({
    businessName: formData.get("businessName"),
    vertical: formData.get("vertical") ?? "",
    contactEmail: formData.get("contactEmail") ?? "",
    currentSiteUrl: formData.get("currentSiteUrl") ?? "",
    pastedSiteText: formData.get("pastedSiteText") ?? "",
    notes: formData.get("notes") ?? "",
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid prospect." };

  const email = parsed.data.contactEmail;
  if (email && !emailCheck.safeParse(email).success) {
    return { error: "Enter a valid contact email or leave it blank." };
  }

  try {
    await db.agencyProspect.create({
      data: {
        businessName: parsed.data.businessName,
        vertical: parsed.data.vertical ? slugify(parsed.data.vertical) : "",
        contactEmail: email || null,
        currentSiteUrl: parsed.data.currentSiteUrl || null,
        pastedSiteText: parsed.data.pastedSiteText,
        notes: parsed.data.notes,
      },
    });
  } catch (err) {
    await logEvent("error", "agency.prospect.add", { message: String(err) });
    return { error: "Could not add the prospect." };
  }
  revalidatePath("/admin/agency/prospects");
  revalidatePath("/admin/agency");
  return { ok: true };
}

/**
 * Paste-a-CSV import. Columns (any order): business/name, vertical, email, url/website, notes.
 * Server-side parse, no enrichment, no scraping. Returns a summary in the channel.
 */
export async function importProspectsCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const csv = String(formData.get("csv") ?? "");
  if (!csv.trim()) return { error: "Paste some CSV rows first." };

  const { headers, rows } = parseCsv(csv);
  if (headers.length === 0 || rows.length === 0) {
    return { error: "Could not find a header row and at least one data row." };
  }
  const alias: Record<string, string> = {
    business: "businessName",
    businessname: "businessName",
    name: "businessName",
    company: "businessName",
    vertical: "vertical",
    category: "vertical",
    type: "vertical",
    email: "contactEmail",
    contactemail: "contactEmail",
    url: "currentSiteUrl",
    website: "currentSiteUrl",
    site: "currentSiteUrl",
    notes: "notes",
    note: "notes",
  };
  const cols = headers.map((h) => alias[h] ?? "");
  if (!cols.includes("businessName")) {
    return { error: "CSV needs at least a 'business' (name) column." };
  }

  let created = 0;
  let skipped = 0;
  for (const r of rows) {
    const rec: Record<string, string> = {};
    cols.forEach((field, i) => {
      if (field) rec[field] = (r[i] ?? "").trim();
    });
    const businessName = (rec.businessName ?? "").trim();
    if (!businessName) {
      skipped++;
      continue;
    }
    const email = (rec.contactEmail ?? "").trim();
    try {
      await db.agencyProspect.create({
        data: {
          businessName: businessName.slice(0, 160),
          vertical: rec.vertical ? slugify(rec.vertical) : "",
          contactEmail: email && emailCheck.safeParse(email).success ? email : null,
          currentSiteUrl: (rec.currentSiteUrl ?? "").slice(0, 300) || null,
          notes: (rec.notes ?? "").slice(0, 2000),
        },
      });
      created++;
    } catch {
      skipped++;
    }
  }
  revalidatePath("/admin/agency/prospects");
  revalidatePath("/admin/agency");
  return { ok: true, error: `Imported ${created} prospect${created === 1 ? "" : "s"}${skipped ? `, skipped ${skipped}` : ""}.` };
}

