}

// ---------------------------------------------------------------------------
// Demo generation + deploy stub
// ---------------------------------------------------------------------------

/**
 * Generate a spec-site demo for a prospect: run the generator (LLM or fallback),
 * render deterministic HTML with the legal guardrails, persist the demo + a
 * generation log, and advance the prospect to GENERATED. No network to the
 * prospect's site; no deploy.
 */
export async function generateDemo(prospectId: string): Promise<ActionState> {
  await requireArea("platform");
  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
  if (!prospect) return { error: "Prospect not found." };

  const vertical = prospect.vertical || "dentist";
  // Pick a matching template if one exists (used to constrain the section schema).
  const dbVertical = await db.agencyVertical.findUnique({
    where: { slug: vertical },
    include: { templates: { orderBy: { createdAt: "asc" }, take: 1 } },
  });
  const template = dbVertical?.templates[0] ?? null;
  const structure = template ? asTemplateStructure(template.structure) : undefined;

  const slug = slugify(prospect.businessName);

  let ir: SiteIR;
  let genMode = "fallback";
  let genModel = "";
  let genOk = true;
  let genMsg = "";
  try {
    const result = await generateSiteIR({
      businessName: prospect.businessName,
      vertical,
      slug,
      pastedSiteText: prospect.pastedSiteText,
      structure,
    });
    ir = result.ir;
    genMode = result.mode;
    genModel = result.model;
    genOk = result.ok;
    genMsg = result.message;
  } catch (err) {
    await logEvent("error", "agency.demo.generate", { message: String(err), prospectId });
    return { error: "Generation failed. Please try again." };
  }

  const rendered = renderSiteHtml(ir);
  if (!rendered.guardrailsOk) {
    // Never persist a demo missing a mandatory legal guardrail.
    await logEvent("error", "agency.demo.guardrails", { prospectId, message: "guardrail assertion failed" });
    return { error: "Render failed a legal guardrail check and was not saved." };
  }

  try {
    const demo = await db.agencyDemoSite.create({
      data: {
        prospectId: prospect.id,
        templateId: template?.id ?? null,
        siteIR: ir as unknown as Prisma.InputJsonValue,
        renderedHtml: rendered.html,
        slug,
        status: "GENERATED",
        noindex: true,
      },
    });
    await db.agencyGenerationLog.create({
      data: { demoId: demo.id, mode: genMode, model: genModel, ok: genOk, message: genMsg.slice(0, 500) },
    });
    if (prospect.status === "PROSPECT") {
      await db.agencyProspect.update({ where: { id: prospect.id }, data: { status: "GENERATED" } });
    }
  } catch (err) {
    await logEvent("error", "agency.demo.persist", { message: String(err), prospectId });
    return { error: "Could not save the generated demo." };
  }

  revalidatePath("/admin/agency/demos");
  revalidatePath("/admin/agency/prospects");
  revalidatePath("/admin/agency");
  return { ok: true };
}

/**
 * STUB deploy. Records the intended host (slug.agency.revsports.ca) and marks the
 * demo DEPLOYED_STUB. Real subdomain provisioning is Phase 2 — nothing is written
 * to nginx, DNS, or the filesystem here.
 */
export async function deployDemoStub(demoId: string): Promise<ActionState> {
  await requireArea("platform");
  const demo = await db.agencyDemoSite.findUnique({ where: { id: demoId }, select: { id: true, slug: true } });
  if (!demo) return { error: "Demo not found." };
  await db.agencyDemoSite
    .update({
      where: { id: demoId },
      data: { status: "DEPLOYED_STUB", intendedHost: intendedHostFor(demo.slug), deployedAt: new Date() },
    })
    .catch(() => null);
  await logEvent("info", "agency.demo.deploy_stub", { demoId, host: intendedHostFor(demo.slug) });
  revalidatePath("/admin/agency/demos");
  revalidatePath("/admin/agency");
  return { ok: true };
}

export async function deleteDemo(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.agencyDemoSite.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/agency/demos");
  revalidatePath("/admin/agency");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Cold Email Engine integration — "Send to outreach"
// ---------------------------------------------------------------------------

/**
 * Create (or link) a Cold Email Business + Contact from a prospect, so the
 * prospect can flow into the existing outreach pipeline. Does NOT send anything —
 * it only creates the CRM records and stamps the prospect SENT. Reuses the
 * coldemail Business/Contact models directly.
 */
export async function sendToOutreach(prospectId: string): Promise<ActionState> {
  await requireArea("platform");
  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
  if (!prospect) return { error: "Prospect not found." };
  if (prospect.outreachBusinessId) {
    return { error: "This prospect is already linked to an outreach business." };
  }

  try {
    const business = await db.business.create({
      data: {
        name: prospect.businessName,
        category: prospect.vertical || "",
        website: prospect.currentSiteUrl || "",
        source: "manual",
      },
    });

    // Attach a contact only when we have a valid, not-already-used email.
    if (prospect.contactEmail && emailCheck.safeParse(prospect.contactEmail).success) {
      const existing = await db.contact.findUnique({
        where: { email: prospect.contactEmail },
        select: { id: true },
      });
      if (!existing) {
        await db.contact.create({
          data: { businessId: business.id, email: prospect.contactEmail },
        });
      }
    }

    await db.agencyProspect.update({
      where: { id: prospect.id },
      data: { outreachBusinessId: business.id, status: prospect.status === "PROSPECT" ? "SENT" : prospect.status === "GENERATED" ? "SENT" : prospect.status },
    });
  } catch (err) {
    await logEvent("error", "agency.outreach.link", { message: String(err), prospectId });
    return { error: "Could not link the prospect to outreach." };
  }

  revalidatePath("/admin/agency/prospects");
  revalidatePath("/admin/coldemail/businesses");
  revalidatePath("/admin/agency");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// CSV parser (server-side, no dependency). Handles quotes, commas, newlines.
// ---------------------------------------------------------------------------

function parseCsv(text: string): { headers: string[]; rows: string[][] } {
  const records: string[][] = [];
  let field = "";
  let row: string[] = [];
  let inQuotes = false;
  const src = text.replace(/\r\n?/g, "\n");
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (inQuotes) {
      if (c === '"') {
        if (src[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n") {
      row.push(field);
      records.push(row);
      row = [];
      field = "";
    } else {
      field += c;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    records.push(row);
  }
  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
  if (nonEmpty.length === 0) return { headers: [], rows: [] };
  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
  return { headers, rows: nonEmpty.slice(1) };
}

