type State = { error?: string; ok?: boolean };
const EMPTY: State = {};

/** Shared error/success banner. On import actions `error` doubles as a summary. */
function Banner({ state, okText }: { state: State; okText: string }) {
  if (state?.error) {
    const good = state.ok; // import summaries set ok + error(message)
    return (
      <div
        className={`rounded-lg border px-3 py-2 text-sm ${
          good
            ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
            : "border-red-500/30 bg-red-500/10 text-red-400"
        }`}
      >
        {state.error}
      </div>
    );
  }
  if (state?.ok) {
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
        {okText}
      </div>
    );
  }
  return null;
}

/** A button that runs a (id) => Promise action inside a transition. */
function ActionButton({
  run,
  children,
  className = "",
  confirm,
  title,
}: {
  run: () => Promise<State>;
  children: React.ReactNode;
  className?: string;
  confirm?: string;
  title?: string;
}) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span className="inline-flex flex-col items-end">
      <button
        type="button"
        disabled={pending}
        title={title}
        className={className || "btn-ghost text-xs"}
        onClick={() => {
          if (confirm && !window.confirm(confirm)) return;
          setErr(null);
          start(async () => {
            const r = await run();
            if (r?.error) setErr(r.error);
          });
        }}
      >
        {pending ? "Working…" : children}
      </button>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </span>
  );
}

