import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { isStaff, canAccess } from "@/lib/rbac";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Serve a generated Sitewave demo's stored HTML for PREVIEW.
 *
 * GET /api/agency/demo/<id>/preview — returns the deterministically rendered,
 * self-contained HTML of the demo (admin/platform staff only). The response
 * carries `X-Robots-Tag: noindex, nofollow` on top of the `<meta robots>` the
 * renderer already bakes in, so a previewed demo can never be indexed. This is a
 * read-only preview surface — it renders stored bytes and provisions nothing.
 */
export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await realUser();
  if (!user || !isStaff(user.role) || !canAccess(user.role, "platform")) {
    return new Response("Not found", { status: 404 });
  }

  const { id } = await ctx.params;
  const demo = await db.agencyDemoSite.findUnique({
    where: { id },
    select: { renderedHtml: true },
  });
  if (!demo || !demo.renderedHtml) {
    return new Response("Demo not found", { status: 404 });
  }

  return new Response(demo.renderedHtml, {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "x-robots-tag": "noindex, nofollow",
      "cache-control": "no-store",
      // Defensive: the demo is self-contained, but forbid it from being framed
      // by any third-party origin.
      "content-security-policy": "frame-ancestors 'self'",
    },
  });
}

/**
 * Sitewave — seed the starter per-vertical template library.
 *
 * Idempotent: upserts each vertical by slug and ensures it has its starter
 * template. Safe to re-run. NOT run automatically by any deploy; run manually
 * against a chosen target, exactly like prisma/seed.ts:
 *
 *   NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed-agency.ts
 *
 * The template `structure` mirrors lib/agency/templates.ts so the DB library and
 * the generator's deterministic fallback stay in lockstep.
 */

import { PrismaClient } from "@prisma/client";
import { assertDbTarget } from "../scripts/db-target-guard.ts";
import { VERTICALS } from "../lib/agency/templates.ts";

assertDbTarget("prisma/seed-agency.ts");

const db = new PrismaClient();

async function main() {
  for (const v of VERTICALS) {
    const vertical = await db.agencyVertical.upsert({
      where: { slug: v.slug },
      update: { name: v.name, description: v.description },
      create: { slug: v.slug, name: v.name, description: v.description },
    });

    const existing = await db.agencyTemplate.findFirst({
      where: { verticalId: vertical.id, name: v.templateName },
      select: { id: true },
    });
    if (existing) {
      await db.agencyTemplate.update({
        where: { id: existing.id },
        data: { structure: v.structure as object },
      });
    } else {
      await db.agencyTemplate.create({
        data: { verticalId: vertical.id, name: v.templateName, structure: v.structure as object },
      });
    }
    console.log(`seeded vertical + template: ${v.slug}`);
  }
}

main()
  .then(() => db.$disconnect())
  .catch(async (err) => {
    console.error(err);
    await db.$disconnect();
    process.exit(1);
  });

