import { test } from "node:test";
import assert from "node:assert/strict";
import {
  coerceSiteIR,
  isRenderableIR,
  slugify,
  asTemplateStructure,
  SECTION_KEYS,
  type SiteIR,
} from "../lib/agency/schema.ts";
import { fallbackIR, verticalBySlug, VERTICALS } from "../lib/agency/templates.ts";
import { renderSiteHtml, esc } from "../lib/agency/render.ts";
import { generateSiteIR } from "../lib/agency/generate.ts";
import { SITEWAVE, disclaimerFor, intendedHostFor } from "../lib/agency/config.ts";

/* ------------------------------------------------------------------ *
 * 1. IR coercion never throws and always yields a renderable shape
 * ------------------------------------------------------------------ */

test("coerceSiteIR fills every field from garbage input", () => {
  const ir = coerceSiteIR(null, { businessName: "Joe's Diner", vertical: "restaurant" });
  assert.equal(ir.businessName, "Joe's Diner");
  assert.equal(ir.vertical, "restaurant");
  assert.ok(ir.hero.headline.length > 0);
  assert.ok(ir.contact.ctaHeadline.length > 0);
  assert.match(ir.palette.primary, /^#[0-9a-fA-F]{6}$/);
  assert.match(ir.palette.accent, /^#[0-9a-fA-F]{6}$/);
});

test("coerceSiteIR rejects a non-hex palette and clamps service/testimonial counts", () => {
  const raw = {
    palette: { primary: "red", accent: "#123456" },
    services: Array.from({ length: 20 }, (_, i) => ({ name: `S${i}`, description: "d" })),
    testimonials: Array.from({ length: 20 }, (_, i) => ({ quote: `q${i}`, author: "a" })),
  };
  const ir = coerceSiteIR(raw, { businessName: "X", vertical: "gym", palette: { primary: "#4F46E5", accent: "#FB7185" } });
  assert.equal(ir.palette.primary, "#4F46E5"); // "red" rejected -> default
  assert.equal(ir.palette.accent, "#123456"); // valid kept
  assert.ok(ir.services.length <= 8);
  assert.ok(ir.testimonials.length <= 6);
});

test("services/testimonials missing required text are dropped", () => {
  const ir = coerceSiteIR(
    { services: [{ description: "no name" }, { name: "Real", description: "ok" }], testimonials: [{ author: "x" }] },
    { businessName: "X", vertical: "salon" }
  );
  assert.equal(ir.services.length, 1);
  assert.equal(ir.services[0].name, "Real");
  assert.equal(ir.testimonials.length, 0);
});

/* ------------------------------------------------------------------ *
 * 2. Fallback IR is complete + renderable for every seeded vertical
 * ------------------------------------------------------------------ */

test("every seeded vertical produces a renderable fallback IR", () => {
  for (const v of VERTICALS) {
    const ir = fallbackIR("Test Business", v.slug);
    assert.ok(isRenderableIR(ir), `${v.slug} fallback should be renderable`);
    assert.equal(ir.vertical, v.slug);
    assert.ok(ir.services.length >= 3);
  }
});

test("unknown vertical slug falls back to the first vertical", () => {
  const ir = fallbackIR("X", "not-a-real-vertical");
  assert.equal(ir.vertical, VERTICALS[0].slug);
});

/* ------------------------------------------------------------------ *
 * 3. Renderer — legal guardrails are ALWAYS present
 * ------------------------------------------------------------------ */

function sampleIR(name = "Joe's Diner"): SiteIR {
  return fallbackIR(name, "restaurant");
}

test("rendered HTML contains every mandatory legal guardrail", () => {
  const { html, guardrailsOk } = renderSiteHtml(sampleIR());
  assert.ok(guardrailsOk);
  assert.match(html, /name="robots"/);
  assert.match(html, /noindex, nofollow/);
  assert.ok(html.includes("Independent concept — not affiliated with"));
  assert.ok(html.includes(SITEWAVE.name));
  // Disclaimer appears in both the banner and the footer.
  const count = html.split("Independent concept — not affiliated with").length - 1;
  assert.ok(count >= 2, "disclaimer must appear in banner AND footer");
});

test("renderer escapes HTML so IR text cannot inject markup", () => {
  const ir = sampleIR("<script>alert(1)</script> & Sons");
  const { html } = renderSiteHtml(ir);
  assert.ok(!html.includes("<script>alert(1)</script>"), "raw script must not appear");
  assert.ok(html.includes("&lt;script&gt;"), "business name must be escaped");
});

test("renderer is deterministic (same IR -> identical HTML)", () => {
  const ir = sampleIR();
  const a = renderSiteHtml(ir).html;
  const b = renderSiteHtml(ir).html;
  assert.equal(a, b);
  // No wall-clock leakage.
  assert.ok(!a.includes(String(new Date().getFullYear() + 1)));
});

test("a non-hex palette in the IR still renders a safe color", () => {
  const ir = sampleIR();
  (ir.palette as { primary: string }).primary = "javascript:alert(1)";
  const { html, guardrailsOk } = renderSiteHtml(ir);
  assert.ok(guardrailsOk);
  assert.ok(!html.includes("javascript:alert(1)"));
});

/* ------------------------------------------------------------------ *
 * 4. Generator degrades gracefully with no API key
 * ------------------------------------------------------------------ */

test("generateSiteIR uses the deterministic fallback when no ANTHROPIC_API_KEY", async () => {
  const prev = process.env.ANTHROPIC_API_KEY;
  delete process.env.ANTHROPIC_API_KEY;
  try {
    const r = await generateSiteIR({ businessName: "Bright Smiles", vertical: "dentist", slug: "bright-smiles" });
    assert.equal(r.mode, "fallback");
    assert.ok(r.ok);
    assert.ok(isRenderableIR(r.ir));
    assert.equal(r.ir.vertical, "dentist");
  } finally {
    if (prev !== undefined) process.env.ANTHROPIC_API_KEY = prev;
  }
});

/* ------------------------------------------------------------------ *
 * 5. Helpers + config
 * ------------------------------------------------------------------ */

test("slugify produces subdomain-safe labels", () => {
  assert.equal(slugify("Joe's Diner & Grill!"), "joe-s-diner-grill");
  assert.equal(slugify(""), "demo");
  assert.ok(slugify("a".repeat(100)).length <= 48);
});

test("intendedHost + disclaimer use the placeholder domain + brand", () => {
  assert.equal(intendedHostFor("joes-diner"), "joes-diner.agency.revsports.ca");
  assert.ok(disclaimerFor("Joe's Diner").includes("not affiliated with Joe's Diner"));
  assert.ok(disclaimerFor("Joe's Diner").includes(SITEWAVE.name));
});

test("asTemplateStructure keeps only known section keys", () => {
  const s = asTemplateStructure({ sections: [{ key: "hero" }, { key: "bogus" }, { key: "contact" }] });
  assert.deepEqual(s.sections.map((x) => x.key).sort(), ["contact", "hero"]);
  for (const k of s.sections.map((x) => x.key)) assert.ok(SECTION_KEYS.includes(k));
});

test("verticalBySlug is case-insensitive", () => {
  assert.equal(verticalBySlug("DENTIST")?.slug, "dentist");
  assert.equal(verticalBySlug("nope"), undefined);
});

test("esc handles all five significant characters", () => {
  assert.equal(esc(`<>&"'`), "&lt;&gt;&amp;&quot;&#39;");
});

