687	  // A sync export in such a file is rejected at `next build` ("Server Actions
688	  // must be async functions") but `tsc --noEmit` passes it — which is exactly how
689	  // the safeNext mistake reached a build. Catch it in the suite instead.
690	  const bad: string[] = [];
